<script setup>
import {ref,watch} from 'vue'
import {newHousehold,classifiedHousehold,exportHousehold,importHousehold,invalidate,setNoise} from './household-check'
const props=defineProps({mode:{type:String,default:'service'}})
const data=ref(newHousehold()), step=ref(0), flags=ref([false,false,false,false,false,false]), result=ref(null), error=ref(''), busy=ref(false)
const titles=['户型与人员','全户新风量','压差与补风','卧室噪声（可选）','条文汇总','合并报告']
let snapshot=''
function mark(index){flags.value=invalidate(flags.value,index); result.value=null}
watch(()=>data.value.ventilation.input,()=>mark(0),{deep:true})
watch(()=>data.value.dwelling.input,()=>mark(2),{deep:true})
watch(()=>data.value.sources,()=>mark(0),{deep:true})
function setField(object,key,value,index){object[key]=value; data.value.sources[`${index===0?'ventrate':'dwelling_pressure'}.${key}`]='用户输入'}
function selectedMethods(room){return Object.entries({换气次数:room.A,人员:room.B,二氧化碳:room.C,甲醛:room.D}).filter(([,value])=>value!=null && Math.abs(value-room.selected)<1e-12).map(([name])=>name).join('、') || '需核对'}
function noise(enabled){setNoise(data.value,enabled)}
function addRoom(){if(data.value.ventilation.input.bedrooms.length<4){data.value.ventilation.input.bedrooms.push({area_m2:10,height_m:data.value.ventilation.input.height_m,occupants:1,activity:'sleeping'});data.value.dwelling.input.bedrooms=data.value.ventilation.input.bedrooms.length}}
function removeRoom(){if(data.value.ventilation.input.bedrooms.length>2){data.value.ventilation.input.bedrooms.pop();data.value.dwelling.input.bedrooms=data.value.ventilation.input.bedrooms.length}}
async function calculate(){
  error.value=''; busy.value=true
  try {const input=exportHousehold(classifiedHousehold(JSON.parse(JSON.stringify(data.value)))); const response=await fetch('/household-check',{method:'POST',headers:{'Content-Type':'application/json'},body:input});const value=await response.json();if(!response.ok)throw new Error(JSON.stringify(value.detail));if(input!==exportHousehold(classifiedHousehold(JSON.parse(JSON.stringify(data.value)))))throw new Error('计算期间输入已更改，请重新计算');result.value=value;snapshot=input;flags.value=[true,true,true,true,true,false]}
  catch(e){error.value=e.message}finally{busy.value=false}
}
async function report(){try{if(!result.value || snapshot!==exportHousehold(classifiedHousehold(JSON.parse(JSON.stringify(data.value)))))throw new Error('输入已更改，请重新计算');const response=await fetch('/household-check/report',{method:'POST',headers:{'Content-Type':'application/json'},body:snapshot});if(!response.ok)throw new Error('报告生成失败');const a=document.createElement('a');a.href=URL.createObjectURL(await response.blob());a.download='一户校核报告.docx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);flags.value[5]=true}catch(e){error.value=e.message}}
function downloadResult(){if(!result.value || snapshot!==exportHousehold(classifiedHousehold(JSON.parse(JSON.stringify(data.value))))) {error.value='输入已更改，请重新计算';return} const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(result.value,null,2)],{type:'application/json'}));a.download='result.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([exportHousehold(classifiedHousehold(JSON.parse(JSON.stringify(data.value))))],{type:'application/json'}));a.download='一户校核.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function load(event){try{data.value=importHousehold(await event.target.files[0].text());flags.value=flags.value.map(()=>false);result.value=null;error.value=''}catch(e){error.value=e.message}}
</script>
<template><el-card><template #header>一户完整校核</template>
<p>六个步骤，可前后切换；输入变化后相关结果标记“需重新计算”。示例参数均须核实。</p><el-alert v-if="props.mode!=='service'" type="info" title="合并校核和 DOCX 目前需要本机服务，请切换计算模式。" :closable="false"/>
<el-alert v-if="error" type="error" :title="error" :closable="false"/><el-steps :active="step" finish-status="success"><el-step v-for="(title,i) in titles" :key="title" :title="title" @click="step=i"/></el-steps>
<div class="buttons"><el-button v-for="(title,i) in titles" :key="title" @click="step=i">{{i+1}} {{title}} · {{flags[i]?'已计算':'需重新计算'}}</el-button></div>
<section v-if="step===0"><h3>户型与人员</h3><label>居住面积 m² <el-input-number :model-value="data.ventilation.input.area_m2" @update:model-value="setField(data.ventilation.input,'area_m2',$event,0)"/></label><label>建筑面积 m² <el-input-number :model-value="data.ventilation.input.floor_area_m2" @update:model-value="setField(data.ventilation.input,'floor_area_m2',$event,0)"/></label><label>净高 m <el-input-number :model-value="data.ventilation.input.height_m" :step="0.1" @update:model-value="setField(data.ventilation.input,'height_m',$event,0)"/></label><label>人数 <el-input-number :model-value="data.ventilation.input.occupants" @update:model-value="setField(data.ventilation.input,'occupants',$event,0)"/></label><div v-for="(room,i) in data.ventilation.input.bedrooms" :key="i"><b>卧室{{i+1}}</b> 面积 <el-input-number v-model="room.area_m2"/> 净高 <el-input-number v-model="room.height_m" :step="0.1"/> 人数 <el-input-number v-model="room.occupants" :min="0"/></div><el-button @click="addRoom">增加卧室</el-button><el-button @click="removeRoom">减少卧室</el-button><div>起居室面积 <el-input-number v-model="data.ventilation.input.living.area_m2"/> 净高 <el-input-number v-model="data.ventilation.input.living.height_m" :step="0.1"/></div></section>
<section v-if="step===1"><h3>全户新风量</h3><p>各房间的 A/B/C/D 方法及取大值由既有模块计算；先完成输入，再计算全部步骤。</p><template v-if="result"><p>全户 {{(result.ventilation.design*3600).toFixed(2)}} m³/h，风机 {{(result.ventilation.fan*3600).toFixed(2)}} m³/h。</p><p v-for="(room,i) in result.ventilation.bedrooms" :key="i">卧室 {{i+1}}：换气次数 {{(room.A*3600).toFixed(2)}}、人员 {{(room.B*3600).toFixed(2)}}、二氧化碳 {{(room.C*3600).toFixed(2)}}、甲醛 {{room.D==null?'未设置':(room.D*3600).toFixed(2)}}；取大值 {{(room.selected*3600).toFixed(2)}} m³/h（来源：{{selectedMethods(room)}}）。</p></template></section>
<section v-if="step===2"><h3>压差与补风</h3><label>油烟机 m³/h <el-input-number :model-value="data.dwelling.input.hood_m3_h" @update:model-value="setField(data.dwelling.input,'hood_m3_h',$event,2)"/></label><label>新风送风 m³/h <el-input-number :model-value="data.dwelling.input.fresh_supply_m3_h" @update:model-value="setField(data.dwelling.input,'fresh_supply_m3_h',$event,2)"/></label><label>机械补风 m³/h <el-input-number v-model="data.dwelling.input.mechanical_makeup_m3_h"/></label><label>自然补风面积 m² <el-input-number v-model="data.dwelling.input.opening_area_m2" :step="0.005"/></label><p>反算采用封闭厨房及默认门缝、起居室送风和厨房补风，与前向所选条件可能不同。15 Pa 为示例提示，不是安全限值。</p><div v-if="result"><div v-for="(scenarios,n) in result.dwelling.scenarios" :key="n"><b>n50 {{n}} 次/h</b><p v-for="(value,name) in scenarios" :key="name">{{name}}：厨房 {{value.pressures_pa.kitchen.toFixed(2)}} Pa</p></div><p v-for="(value,n) in result.inverse" :key="n">n50 {{n}} 最小机械补风 {{(value.mechanical.value*3600).toFixed(2)}} m³/h，自然有效面积 {{(value.opening.value*10000).toFixed(2)}} cm²</p></div></section>
<section v-if="step===3"><h3>卧室噪声</h3><el-switch :model-value="!!data.ventilation.input.noise" @change="noise"/> 启用示例噪声初筛；频谱与衰减是假设。<div v-if="data.ventilation.input.noise"><label v-for="(frequency,i) in [63,125,250,500,1000,2000,4000,8000]" :key="frequency">{{frequency}} Hz 声功率 dB <el-input-number v-model="data.ventilation.input.noise.fan_power_db[i]"/></label><label>测点距离 m <el-input-number v-model="data.ventilation.input.noise.distance_m" :step="0.1"/></label><label>房间常数 m² <el-input-number v-model="data.ventilation.input.noise.room_constant_m2"/></label></div><div v-if="result?.ventilation.noise"><p v-for="row in result.ventilation.noise.settings" :key="row.flow_m3_s">{{(row.flow_m3_s*3600).toFixed(1)}} m³/h：{{row.a_weighted_db.toFixed(2)}} dB(A)</p></div></section>
<section v-if="step===4"><h3>条文汇总</h3><div v-for="group in ['应','宜','其他']" :key="group"><h4>{{group}}</h4><p v-for="(check,i) in (result?.checks||[]).filter(x=>group==='其他'?!['应','宜'].includes(x.strength):x.strength===group)" :key="i">{{check.explanation}}：{{check.passed?'满足':'不满足'}}</p></div></section>
<section v-if="step===5"><h3>合并报告</h3><p>报告记录输入、各步结果、来源分级和软件版本。</p><el-button :disabled="!result || props.mode!=='service'" @click="report">下载 DOCX</el-button><el-button :disabled="!result" @click="downloadResult">下载完整结果 JSON</el-button></section>
<div class="buttons"><el-button :disabled="step===0" @click="step--">上一步</el-button><el-button :disabled="step===5" @click="step++">下一步</el-button><el-button type="primary" :disabled="props.mode!=='service'" :loading="busy" @click="calculate">计算全部步骤</el-button><el-button @click="download">导出一户算例</el-button><label>导入一户算例<input type="file" accept=".json" @change="load"/></label></div>
</el-card></template>
<style scoped>.buttons{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}label{display:inline-block;margin:8px}pre{overflow:auto}</style>
